claim_job(job_id)
if cancellation_requested(job_id):
    mark_cancelled(job_id)
else:
    mark_running(job_id)
    try:
        for step in workflow_steps(job_id):
            if cancellation_requested(job_id):
                mark_cancelled(job_id)
                break
            result = run_step_idempotently(step)
            persist_checkpoint(job_id, result)
        else:
            mark_completed_with_result(job_id)
    except TransientError:
        schedule_bounded_retry(job_id)
    except PermanentError:
        mark_failed_with_safe_error_code(job_id)
